115	grpc_error* TlsCheckHostName(const char* peer_name, const tsi_peer* peer) {
116	  /* Check the peer name if specified. */
117	  if (peer_name != nullptr && !grpc_ssl_host_matches_name(peer, peer_name)) {
118	    char* msg;
119	    gpr_asprintf(&msg, "Peer name %s is not in peer certificate", peer_name);
120	    grpc_error* error = GRPC_ERROR_CREATE_FROM_COPIED_STRING(msg);
121	    gpr_free(msg);
122	    return error;
123	  }
124	  return GRPC_ERROR_NONE;
125	}
