155	void TlsChannelSecurityConnector::add_handshakers(
156	    const grpc_channel_args* args, grpc_pollset_set* /*interested_parties*/,
157	    grpc_core::HandshakeManager* handshake_mgr) {
158	  if (RefreshHandshakerFactory() != GRPC_SECURITY_OK) {
159	    gpr_log(GPR_ERROR, "Handshaker factory refresh failed.");
160	    return;
161	  }
162	  // Instantiate TSI handshaker.
163	  tsi_handshaker* tsi_hs = nullptr;
164	  tsi_result result = tsi_ssl_client_handshaker_factory_create_handshaker(
165	      client_handshaker_factory_,
166	      overridden_target_name_ != nullptr ? overridden_target_name_.get()
167	                                         : target_name_.get(),
168	      &tsi_hs);
169	  if (result != TSI_OK) {
170	    gpr_log(GPR_ERROR, "Handshaker creation failed with error %s.",
171	            tsi_result_to_string(result));
172	    return;
173	  }
174	  // Create handshakers.
175	  handshake_mgr->Add(grpc_core::SecurityHandshakerCreate(tsi_hs, this, args));
176	}
