169	  grpc_tls_key_materials_config::PemKeyCertPairList cert_pair_list;
170	  for (size_t i = 0; i < num; i++) {
171	    grpc_core::PemKeyCertPair key_cert_pair(
172	        const_cast<grpc_ssl_pem_key_cert_pair*>(key_cert_pairs[i]));
173	    cert_pair_list.emplace_back(std::move(key_cert_pair));
174	  }
175	  config->set_key_materials(std::move(pem_root), std::move(cert_pair_list));
176	  gpr_free(key_cert_pairs);
177	  return 1;
178	}
